from __future__ import annotations
from pathlib import Path
ROOT = Path(__file__).resolve().parents[2]

def replace_once(relative: str, old: str, new: str) -> None:
    path = ROOT / relative
    source = path.read_text(encoding="utf-8")
    count = source.count(old)
    if count != 1:
        raise RuntimeError(f"{relative}: expected one replacement, found {count}")
    path.write_text(source.replace(old, new, 1), encoding="utf-8")

replace_once('metric_rca/runtime/ranking.py', 'def _interaction_promoted_candidate(\n    *,\n    repository: Any,\n    run_id: str,\n    metric_id: str,\n    ranked_candidates: list[RootCauseCandidate],\n) -> RootCauseCandidate | None:\n    if metric_id not in {"gmv", "uv"}:\n        return None\n    if not _target_is_bad_direction_anomaly(repository=repository, run_id=run_id):\n        return None\n    for candidate in ranked_candidates:\n        if candidate.root_cause_type == RootCauseType.INTERACTION_CHANNEL_CATEGORY.value:\n            return candidate.model_copy(\n                update={\n                    "evidence_ids": _interaction_evidence_ids(\n                        repository=repository,\n                        run_id=run_id,\n                        pairs=_candidate_pairs(candidate),\n                        base_evidence_ids=candidate.evidence_ids,\n                    )\n                }\n            )\n        if candidate.dimension not in {"channel", "category"}:\n            continue\n        if _has_matching_signal_evidence(\n            repository=repository,\n            run_id=run_id,\n            candidate=candidate,\n            required_bad_direction=True,\n        ):\n            continue\n        pairs = _candidate_pairs(candidate)\n        if not _has_dimension(pairs, "channel") or not _has_dimension(pairs, "category"):\n            continue\n        if _has_any_pair_matching_signal_evidence(\n            repository=repository,\n            run_id=run_id,\n            pairs=pairs,\n            required_bad_direction=True,\n        ):\n            continue\n        evidence_ids = _interaction_evidence_ids(\n            repository=repository,\n            run_id=run_id,\n            pairs=pairs,\n            base_evidence_ids=candidate.evidence_ids,\n        )\n        e_rank_id = f"{run_id}:E_rank"\n        if e_rank_id not in evidence_ids:\n            evidence_ids.append(e_rank_id)\n        return candidate.model_copy(\n            update={\n                "root_cause_type": RootCauseType.INTERACTION_CHANNEL_CATEGORY.value,\n                "evidence_ids": evidence_ids,\n            }\n        )\n    return None\n', 'def _interaction_promoted_candidate(\n    *,\n    repository: Any,\n    run_id: str,\n    metric_id: str,\n    ranked_candidates: list[RootCauseCandidate],\n) -> RootCauseCandidate | None:\n    if metric_id not in {"gmv", "uv"}:\n        return None\n    if not _target_is_bad_direction_anomaly(repository=repository, run_id=run_id):\n        return None\n    for candidate in ranked_candidates:\n        pairs = _candidate_pairs(candidate)\n        if candidate.root_cause_type == RootCauseType.INTERACTION_CHANNEL_CATEGORY.value:\n            if not _has_verified_interaction_mechanism_evidence(\n                repository=repository,\n                run_id=run_id,\n                candidate=candidate,\n                required_bad_direction=True,\n            ):\n                continue\n            return candidate.model_copy(\n                update={\n                    "evidence_ids": _interaction_evidence_ids(\n                        repository=repository,\n                        run_id=run_id,\n                        pairs=pairs,\n                        base_evidence_ids=candidate.evidence_ids,\n                    )\n                }\n            )\n        if candidate.dimension not in {"channel", "category"}:\n            continue\n        if not _has_dimension(pairs, "channel") or not _has_dimension(pairs, "category"):\n            continue\n        if _has_matching_signal_evidence(\n            repository=repository,\n            run_id=run_id,\n            candidate=candidate,\n            required_bad_direction=True,\n            excluded_signal_type="interaction",\n        ):\n            continue\n        if _has_any_pair_matching_signal_evidence(\n            repository=repository,\n            run_id=run_id,\n            pairs=pairs,\n            required_bad_direction=True,\n            excluded_signal_type="interaction",\n        ):\n            continue\n        if not _has_verified_interaction_mechanism_evidence(\n            repository=repository,\n            run_id=run_id,\n            candidate=candidate,\n            required_bad_direction=True,\n        ):\n            continue\n        evidence_ids = _interaction_evidence_ids(\n            repository=repository,\n            run_id=run_id,\n            pairs=pairs,\n            base_evidence_ids=candidate.evidence_ids,\n        )\n        e_rank_id = f"{run_id}:E_rank"\n        if e_rank_id not in evidence_ids:\n            evidence_ids.append(e_rank_id)\n        return candidate.model_copy(\n            update={\n                "root_cause_type": RootCauseType.INTERACTION_CHANNEL_CATEGORY.value,\n                "evidence_ids": evidence_ids,\n            }\n        )\n    return None\n')

